        EngineParameter(key: "assumeMultipleStartingBlackMovesAreHandicap", kind: .bool, timing: .launch, section: "Handicap", summary: "Assume that if black makes many moves in a row right at the start of the game, then the game is a handicap game. This is necessary on some servers and for some GUIs and also when initializing from many SGF files, which may set up a handicap game using repeated GTP \"play\" commands for black rather than GTP \"place_free_handicap\" commands; however, it may also lead to incorrect understanding of komi if whiteHandicapBonus is used and a server does not have such a practice. Uncomment and set to false to disable.", exampleValue: "true"),
        EngineParameter(key: "autoAvoidRepeatDir", kind: .text, timing: .launch, section: "Automatic avoid patterns", summary: "Directory to auto-save moves KataGo plays, to avoid them in future games. You can create a new empty directory and put its path here. If you run parallel instances of KataGo, use different directories if you want them not to share their biases, use the same directory if you want all of them to bias away from past moves that any of them have played. KataGo will also automatically DELETE old data in this directory, so it is recommended that if you do share the same directory between parallel instances, that they all use the same settings that affect data saving/deletion.", exampleValue: "PATH_TO_NEW_DIRECTORY"),
        EngineParameter(key: "autoAvoidRepeatSaveChunkSize", kind: .integer(1...10000), timing: .launch, section: "Automatic avoid patterns", summary: "Affects data saving/deletion. Within a single run of a program, wait to accumulate this many samples (possibly across multiple clear_boards/games) before saving the data. Can help to avoid writing too many small files to disk, especially when GTP is used in a way that clears the board very frequently (e.g. gtp2ogs pooled manager).", exampleValue: "200"),
