        EngineParameter(key: "chosenMoveTemperatureHalflife", kind: .real(0.1...100000.0), timing: .live, section: "Root move selection and biases", summary: "Decay temperature for the early game by 0.5 every this many moves, scaled with board size.", exampleValue: "19"),
        EngineParameter(key: "chosenMoveTemperatureOnlyBelowProb", kind: .real(0.0...1.0), timing: .live, section: "OTHER USEFUL PARAMETERS FOR HUMAN PLAY ADJUSTMENT", summary: "Choosing temperature near 1, and restricting it to only affect moves already below 1% chance, so that we sample close to the full range of human play. You can also reduce the temperature to settings more like the plain gtp_example.cfg. Then, rather than imitating a realistic human player, it will be more like imitating the *majority vote* of players at that rank. For example it would avoid a lot of blunders that players of that level would make, because even if players often blunder, the *majority vote* of players would be much less likely to select any given blunder that an individual player would.", exampleValue: "0.01"),
